Translate("deDE", "the-stockade", {
	title = "Das Verlies",
	aliases = { "Verlies", "Verlies von Stormwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Verlies ist das Gefängnis von {link:stormwind-city}Stormwind{/link}. Es liegt unter der Stadt, hinter einem finsteren Tor an den Kanälen nahe dem {link:mage-quarter}Magierviertel{/link}. Seine Zellen halten die schlimmsten Verbrecher des Königreichs: Mörder, Rebellen, Plünderer der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} und vor allem die gefangenen Männer der {link:defias-brotherhood}Bruderschaft der Defias{/link}. Jahrelang war es die stille Antwort auf jede Unordnung im Reich. Nun ist es selbst eine Unordnung. Die Gefangenen haben sich erhoben, ihre Wachen vertrieben und die Zellentrakte an sich gerissen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann das Verlies erbaut wurde oder wer zuerst seine Schlüssel verwahrte. Je dreister die {link:defias-brotherhood}Defias{/link} in {link:westfall}Westfall{/link} und {link:elwynn-forest}Elwynn{/link} wurden, desto mehr seiner Zellen füllten sich mit Männern in roten Halstüchern.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Der Aufstand begann unter den Gefangenen der {link:defias-brotherhood}Defias{/link} und griff auf jeden Trakt über. {link:warden-thelwater}Aufseher Thelwater{/link} und seine Wachen halten nur noch den Eingang. Drinnen beherrschen die Häftlinge die Gänge, und die gefährlichsten unter ihnen haben die Zellen zu ihren Festungen gemacht. An ihrer Spitze steht {link:bazil-thredd}Bazil Thredd{/link}, einer der Leutnants von {link:edwin-vancleef}Edwin VanCleef{/link}. Thredd erhob sich nicht allein. Vor dem Aufstand empfing er einen Besucher von jenseits der Mauern, und die Spur dieses Besuchers führt zur {link:stormwind-keep}Burg Stormwind{/link}.]=],
		},
		{
			title = "Häftlinge",
			text = [=[• {b}{link:bazil-thredd}Bazil Thredd{/link}.{/b} Der Leutnant der {link:defias-brotherhood}Defias{/link}, der den Aufstand anführt.
• {b}{link:targorr-the-dread}Targorr der Schreckliche{/link}.{/b} Ein Gefangener, dessen Verbrechen {link:lakeshire}Seenhain{/link} nicht vergeben hat.
• {b}{link:kam-deepfury}Kam Deepfury{/link}.{/b} Ein Gefangener der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}, den die {link:dwarves}Zwerge{/link} von {link:dun-modr}Dun Modr{/link} suchen.
• {b}{link:dextren-ward}Dextren Ward{/link}.{/b} Ein Verbrecher, dessen Hand {link:shadow-council}der Rat{/link} von {link:darkshire}Dunkelhain{/link} gefordert hat.
• {b}{link:hamhock}Hamhock{/link}.{/b} Ein {link:ogres}Oger{/link} von großer Gestalt und wenig Geduld, der frei zwischen den Zellen umgeht.
• {b}{link:bruegal-ironknuckle}Bruegal Ironknuckle{/link}.{/b} Ein selten gesehener und sehr gefürchteter Gefangener der tiefsten Trakte.
• {b}Die Häftlinge der Defias.{/b} Gefangene, Sträflinge, Inhaftierte und Aufständische, die nun die Gänge beherrschen.]=],
		},
		{
			title = "Überlieferungen des Gefängnisses",
			text = [=[• Die Städte des Königreichs haben ein langes Gedächtnis. {link:lakeshire}Seenhain{/link}, {link:darkshire}Dunkelhain{/link} und die {link:dwarves}Zwerge{/link} des Sumpflands haben hier jeweils einen Gefangenen, den sie für seine Verbrechen büßen sehen wollen.
• Die roten Halstücher der {link:defias-brotherhood}Defias{/link} werden selbst in den Zellen getragen. In der {link:old-town}Altstadt{/link} hat Nikova Raskol eine große Menge davon verlangt.
• Der Aufstand im Verlies ist nicht nur Sache des Aufsehers. Er ist der erste Faden einer Verschwörung, die von den {link:the-deadmines}Todesminen{/link} bis zur {link:stormwind-keep}Burg Stormwind{/link} reicht.]=],
		},
	},
})

Translate("deDE", "bazil-thredd", {
	title = "Bazil Thredd",
	subtitle = "Anführer des Aufstands im Verlies",
	found = "Der tiefste Zellentrakt des Verlieses",
	hint = [=[Stellt Euch dem Leutnant der Defias, der den Aufstand im Verlies anführt.]=],
	allegiance = "Bruderschaft der Defias",
	aliases = { "Thredd" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bazil Thredd ist ein Leutnant von {link:edwin-vancleef}Edwin VanCleef{/link} und ein Hauptmann der {link:defias-brotherhood}Bruderschaft der Defias{/link}. Die Krone ließ ihn im {link:the-stockade}Verlies{/link} einsperren. Die Mauern hielten ihn nicht lange. Nun führt er den Aufstand an, der das Gefängnis von {link:stormwind-city}Stormwind{/link} in eine Festung der Defias unter der {link:capital-city}Hauptstadt{/link} verwandelt hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thredd ist mehr als ein Aufrührer. Sein Aufstand war geplant, und jemand außerhalb des Gefängnisses half ihm bei der Planung. Durch Thredd trägt die Bruderschaft ihren Krieg von den Feldern von {link:westfall}Westfall{/link} bis ins Herz von {link:stormwind-city}Stormwind{/link} selbst.

Seine Revolte zeigt auch, dass die Bruderschaft die Ihren nicht im Stich lässt. Die Männer, die die Krone gefangen genommen hatte, erhoben sich in eben dem Gefängnis, das sie brechen sollte, und das {link:the-stockade}Verlies{/link} wurde zu einer zweiten Festung der {link:defias-brotherhood}Defias{/link} unter der {link:capital-city}Hauptstadt{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er diente {link:edwin-vancleef}VanCleef{/link} als einer der Leutnants der Bruderschaft.
• Er führte die Gefangenen des Verlieses in die Revolte gegen ihre Wachen.
• Er empfing einen geheimen Besucher, bevor der Aufstand begann.]=],
		},
	},
	chapters = {
		{
			title = "Der Aufstand",
			hint = "Macht dem Anführer des Aufstands im Verlies ein Ende.",
			text = [=[{link:warden-thelwater}Aufseher Thelwater{/link} konnte sein Gefängnis nicht zurückerobern, solange Thredd lebte. Als der Leutnant in den Tiefen des Verlieses fiel, verlor der Aufstand seinen Kopf. Sein eigener Kopf wurde zum Aufseher ans Tor zurückgebracht.]=],
		},
		{
			title = "Der Besucher",
			hint = "Findet heraus, wer Bazil Thredd vor dem Aufstand besuchte.",
			text = [=[Der Aufseher erinnerte sich an einen seltsamen Besucher, der kurz vor der Erhebung an Thredds Zelle gekommen war. Er schrieb alles auf, woran er sich erinnern konnte, und versiegelte es. Diese versiegelte Beschreibung gelangte vom {link:the-stockade}Verlies{/link} zum Stadtarchitekten und von ihm zum Meister von {link:si-7}SI:7{/link}. Am Ende führte sie zu einem Verräter in der {link:stormwind-keep}Burg Stormwind{/link}.]=],
		},
	},
	mentions = {
		{ text = "Der nie abgeschickte Brief" },
		{ text = "Bazil Thredd" },
		{ text = "Der Aufstand im {link:the-stockade}Verlies{/link}" },
		{ text = "Der seltsame Besucher" },
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "sein Herr" },
		{ id = "warden-thelwater", name = "Aufseher Thelwater", note = "sein Kerkermeister" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "setzte die Jagd auf ihn in Gang" },
		{ id = "gregor-lescovar", name = "Gregor Lescovar", note = "der Verräter, zu dem sein Besucher führte" },
	},
})

Translate("deDE", "targorr-the-dread", {
	title = "Targorr der Schreckliche",
