		{
			title = "Bedeutung",
			text = [=[Targorr zeigt, wie weit die Verbrechen des Königreichs reichen. Die Gerechtigkeit schickte ihn in die {link:capital-city}Hauptstadt{/link}, und {link:lakeshire}Seenhain{/link} wartet noch immer darauf, dass sie vollendet wird.]=],
		},
		{
			title = "Taten",
			text = [=[• Er beging Verbrechen, die ihm den Hass Seenhains einbrachten.
• Er brach während des Aufstands aus seiner Zelle aus.]=],
		},
	},
	mentions = {
		{ text = "Wie man sät..." },
	},
	bonds = {
		{ id = "bazil-thredd", name = "Bazil Thredd", note = "führt den Aufstand an, dem er sich anschloss" },
	},
})

